import {importCSV,assessDataset,canonicalHeader} from './analytics/data-quality.js';
export function attachMemberRows(meetings,memberRecords){const byDate=new Map(),warnings=[];for(const [i,raw]of memberRecords.entries()){const r=Object.fromEntries(Object.entries(raw).map(([k,v])=>[canonicalHeader(k),v])),date=String(r.meeting_date??r.date??'').trim(),id=String(r.anonymous_member_id??'').trim();if(!date&&!id)continue;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!id||id.length>80){warnings.push(`Members row ${i+2} needs a date and anonymous ID.`);continue}if(!byDate.has(date))byDate.set(date,[]);byDate.get(date).push(id)}const dateCounts=new Map();meetings.forEach(r=>dateCounts.set(r.date,(dateCounts.get(r.date)??0)+1));for(const date of byDate.keys())if(!dateCounts.has(date))warnings.push(`Members dated ${date} have no matching meeting and were ignored.`);return{rows:meetings.map(r=>{if(!byDate.has(r.date))return r;if(dateCounts.get(r.date)!==1){warnings.push(`Members for ${r.date} could not be joined because multiple meetings share that date.`);return r}return{...r,members:byDate.get(r.date)}}),warnings}}
export function parseWorkbook(bytes,XLSX){if(bytes.byteLength>3*1024*1024)throw Error('Choose a spreadsheet smaller than 3 MB.');let wb;try{wb=XLSX.read(bytes,{type:'array',cellDates:true,sheetRows:2002,cellFormula:false,cellHTML:false})}catch{throw Error('This workbook could not be read. Save it as XLSX or export Meetings as CSV.')}const name=wb.SheetNames.find(n=>n.toLowerCase()==='meetings')??(wb.SheetNames.length===1?wb.SheetNames[0]:null);if(!name)throw Error('Name your meeting-data tab “Meetings” so we know which sheet to analyze.');if(wb.Sheets[name]['!fullref']&&XLSX.utils.decode_range(wb.Sheets[name]['!fullref']).e.r>2000)throw Error('The Meetings tab exceeds 2,000 rows. Remove unused formatted rows or export a CSV.');const matrix=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:'',raw:true,blankrows:false});if(matrix.length>2001)throw Error('Import up to 2,000 meetings.');if(matrix.length<2)throw Error('Add at least one meeting below the header row.');const width=matrix[0].length;for(const r of matrix)while(r.length<width)r.push('');const csv=matrix.map(row=>row.map(v=>'"'+String(v instanceof Date?v.toISOString().slice(0,10):v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const checked=importCSV(csv),memberSheet=wb.SheetNames.find(n=>n.toLowerCase()==='members');if(memberSheet){const ms=wb.Sheets[memberSheet];if(ms['!fullref']&&XLSX.utils.decode_range(ms['!fullref']).e.r>=2001)throw Error('The optional Members tab supports up to 2,000 rows. Use inline anonymous IDs for larger attendance lists.');const records=XLSX.utils.sheet_to_json(ms,{defval:'',raw:true}).map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,v instanceof Date?v.toISOString().slice(0,10):v]))),joined=attachMemberRows(checked.rows,records),validated=assessDataset(joined.rows);checked.rows=validated.rows;checked.quality.warnings.push(...joined.warnings,...validated.quality.fieldIssues.map(x=>x.reason));checked.quality.fieldIssues.push(...validated.quality.fieldIssues);checked.quality.missingFields=validated.quality.missingFields;checked.quality.analysisReadiness=validated.quality.analysisReadiness}return checked}
export async function importFile(file){if(file.size>3*1024*1024)throw Error('Choose a spreadsheet smaller than 3 MB.');if(/\.csv$/i.test(file.name))return importCSV(await file.text());if(/\.xlsx$/i.test(file.name)){const XLSX=await import('./vendor/xlsx.mjs');return parseWorkbook(await file.arrayBuffer(),XLSX)}throw Error('Choose a CSV or XLSX file. Export other formats from your spreadsheet first.')}
